def to_cents(text):
    """'SGD 8.00' -> 800, '$10' -> 1000. None if negative or unparseable."""
    s = text.strip()
    if s.startswith('SGD'):
        s = s[3:].strip()
    if s.startswith('$'):
        s = s[1:].strip()
    if s.startswith('-'):                            # a negative amount (even -0) is invalid
        return None
    whole, dot, frac = s.partition('.')
    if not whole.isdecimal():                        # need at least one digit before any dot
        return None
    if dot and not (1 <= len(frac) <= 2 and frac.isdecimal()):
        return None                                  # after a dot: 1 or 2 digits only
    return int(whole) * 100 + int(frac.ljust(2, '0'))  # integer cents: no float rounding

def solution(staff, claims):
    rebate = {}                                      # staff_pass_id -> cents (or None)
    for pass_id, _team, text in staff:
        rebate[pass_id] = to_cents(text)
    claimed = set()                                  # (staff_pass_id, day) already paid
    out = []
    for pass_id, day in claims:
        if pass_id not in rebate:
            out.append('UNKNOWN')
        elif rebate[pass_id] is None:
            out.append('INVALID')
        elif (pass_id, day) in claimed:
            out.append('ALREADY_CLAIMED')
        else:
            claimed.add((pass_id, day))
            out.append('PAID ' + str(rebate[pass_id]))
    return out

