def parse(text):
    # Hand-rolled parser, character by character; returns cents or None
    s = text.strip()
    if s[:3] == 'SGD':
        s = s[3:].strip()
    if s[:1] == '$':
        s = s[1:].strip()
    if s == '' or s[0] == '-':
        return None
    parts = s.split('.')
    if len(parts) > 2 or parts[0] == '' or not all(c in '0123456789' for c in parts[0]):
        return None
    cents = int(parts[0]) * 100
    if len(parts) == 2:
        d = parts[1]
        if not (1 <= len(d) <= 2) or not all(c in '0123456789' for c in d):
            return None
        cents += int(d) * (10 if len(d) == 1 else 1)
    return cents

def solution(staff, claims):
    # Linear search for every claim, and a list of past payouts (slow)
    paid = []
    out = []
    for pass_id, day in claims:
        row = None
        for s in staff:
            if s[0] == pass_id:
                row = s
                break
        if row is None:
            out.append('UNKNOWN')
            continue
        cents = parse(row[2])
        if cents is None:
            out.append('INVALID')
        elif [pass_id, day] in paid:
            out.append('ALREADY_CLAIMED')
        else:
            paid.append([pass_id, day])
            out.append('PAID ' + str(cents))
    return out
